"""逐课真实情境：初级。教学设计，不是已执行的软件操作记录。"""
SCENARIOS = {
'A02': dict(place='P01｜庭院入口的台阶', before='方块挡住入口；学员容易把观察视角变化误当物体移动。', after='同一方块成为入口旁的低台阶，能指出改了位置、旋转还是尺寸。', task='基于我提供的场景只准备地面和一块台阶。显示世界坐标轴，分别演示移动、旋转、缩放，保留可撤销的初始状态；不要加入角色控制代码。', keep='地面、相机和坐标约定保持不变；对象变换不等于编辑网格。', tweaks=[('Godot Inspector > Transform（内置）','先只改Position Y，再还原；然后单独改Scale X','物体相对地面的高度和宽度，而不是屏幕上的左右'),('Blender Item > Transform（内置）','核对本软件竖直轴；把位置与Dimensions/Scale分开看','Scale为1是否真的意味着目标尺寸')], accept=['能选中正确对象完成三种变化并恢复原值。','面对入口被挡的问题，能选择该移动还是改变尺寸，而不重建整个场景。'], regress='相机仍能看见地面，地面和其他对象未被误改。', transfer='把台阶换成路牌，目标改为转朝玩家；解释为什么不应移动全部顶点。', risk='检查AI是否把屏幕方向当世界方向、把Blender轴约定直接套到Godot。'),
'A07': dict(place='P01/P02｜庭院门轴与镜头支点', before='门绕中心转，或父节点转向后物体朝意外方向移动。', after='门围绕侧边开合；能区分父相对位置、自身方向、世界方向。', task='准备一块门板和一个独立父支点。两种支点方案在关门时保持门板同一位置；只变支点关系，对比开门90度。另用有鼻子的方块演示三种移动参照，不推矩阵。', keep='门板大小、关门位置和开门角相同；不引入角色绑定。', tweaks=[('Godot Node3D父子Transform（内置）','改支点位置，同时调整门板相对位置','关门外观是否不变、开门时铰链侧是否固定'),('Blender Origin与工具Pivot（概念/入口）','分别确认对象原点与本次操作支点','是否只改变工具操作方式，却没有改变导出后的门轴')], accept=['能在三种参照下预测方向，用一次移动验证。','能保持关门位置并修正门轴；说清是谁绕谁转。'], regress='门框没有移动；原有相机和场景整体变换不受影响。', transfer='把门换成风车，选择中心轴，并说明门的侧轴为什么不适用。', risk='检查AI是否把Inspector的局部position说成物体自身轴，或把临时Pivot等同导出原点。'),
'A03': dict(place='P01｜可复用的围栏模块', before='移动围栏外观后功能部分留在原处；每个模块都被重复从零搭建。', after='两份模块实例能独立摆放，换一个外观不删掉原功能。', task='在现有灰盒准备一个父节点包装的围栏模块与两个实例，标明外观节点和预留功能节点。给出整体移动与只移动外观的对照，限定修改当前模块。', keep='原项目入口、其他场景与功能节点保持；只读懂职责，不先搭通用架构。', tweaks=[('Godot Scene树与Inspector（内置）','分别选模块根和Visual改Position','哪些子对象跟随，哪些没有跟随'),('Godot网格吸附（内置入口）','用统一间距摆两个实例','整体连接处是否错位，是否误改共享源')], accept=['能解释节点、场景和实例在这两个围栏中的区别。','能指出AI改动范围、回退一次错位，保留同一目标平台记录。'], regress='原场景入口可打开；另一个实例和功能包装仍在。', transfer='用同一包装换成邮箱外观，判断应修改哪层。', risk='检查AI是否删除整个实例来替换外观，或把所有实例误当独立资源副本。'),
'A05': dict(place='P02｜从出生点走到第一颗星的位置', before='走路速度不合适，或者不同运行条件下单位时间位移不一致。', after='走与跑有可感知差异，斜向没有不合理加速；调整速度不改变关卡尺寸。', task='只为已有玩家准备WASD走路和Shift跑步，复用已有地面碰撞。暴露walk_speed与run_speed这两个项目自定义参数，附固定时长位移对照；解释velocity与位移，不能给move_and_slide速度重复乘delta。', keep='地面碰撞、相机、出生点和场景比例保持；不增加体力条或动画状态机。', tweaks=[('玩家脚本导出变量（自定义）','walk_speed从记录基线略调，再固定路线试走','到目标所需时间和转向控制感'),('玩家脚本导出变量（自定义）','单独调run_speed，不同时改相机FOV','跑步是否确实更快且不会越过目标')], accept=['能用输入动作启动走跑，手调速度并说明选择。','能读固定时长位移结果，区分速度错误与关卡尺度错误。'], regress='墙仍阻挡玩家；停止输入后行为符合本课设定；其他对象未移动。', transfer='把直线目标换成绕两根柱子，重新判断速度是否舒服。', risk='检查API版本、重复delta、斜向加速；这些是要测试的风险，不是某模型必然失败。'),
'A04': dict(place='P02｜石墙阻挡与星星检测区', before='看得见的墙可以穿过，或星星区域不识别玩家。', after='墙负责阻挡，区域只负责检测；仅选定对象触发。', task='准备一堵可单独隐藏外观/禁用形状的墙，再准备只显示进入次数的Area。先显示实际层号和检测方向，只注入一处Mask错误；本课不制作完整拾取计分。', keep='玩家控制器与墙位置固定；不能通过全选所有层或删除碰撞需求修复。', tweaks=[('CollisionShape3D > Disabled（内置）','恢复基线后只切换一次Disabled','阻挡消失与隐藏Mesh的结果是否不同'),('Area3D > Collision Mask（内置）','按玩家实际所属层勾选，不背位掩码数字','玩家进入和错误对象进入是否得到不同结果')], accept=['能用隐藏外观/禁用形状两次对照分清视觉、阻挡和检测。','能修一处检测对象错误，并说明为什么不用复杂高模碰撞。'], regress='恢复后墙继续阻挡；检测区不变成实体障碍。', transfer='换成树：决定树干和树冠是否要碰撞，按玩法给理由。', risk='检查AI是否用外观代替物理形状、误解Layer/Mask或扩大检测范围掩盖问题。'),
'A06': dict(place='P02｜到达低平台', before='平台跳不上去，或可以在空中无限起跳。', after='低平台可到达；跳跃高度与滞空可调，落地规则稳定。', task='复用玩家移动，只加落地后起跳和持续重力。暴露jump_velocity与gravity为项目变量，提供一条固定平台测试路线；不自动改变平台高度来掩盖错误。', keep='walk_speed、平台尺寸、相机不变；不做通用爬楼梯、二段跳或复杂容错系统。', tweaks=[('玩家导出jump_velocity（自定义）','固定gravity，只调整起跳初速度','是否越过平台边缘、最高点和落地点'),('玩家导出gravity（自定义）','恢复起跳值，再单独调重力','滞空时间、落地节奏；本课不求公式')], accept=['能说明并验证两个参数的影响，选择一组合适手感。','连续测试起跳、空中再按、落地再跳，解释门控条件。'], regress='走跑和墙碰撞未退化；坠落恢复策略保持。', transfer='同高度平台改为更远，区分该改横向速度、起跳还是布局。', risk='检查AI是否把脚接近地面误当已落地、无限重设竖直速度或偷偷移动平台。'),
'A08': dict(place='P02｜绕围墙探索时的第三人称镜头', before='靠墙镜头被遮挡，或者抬头时玩家运动方向异常。', after='可观察前路和落点，转视角后移动仍合理。', task='复用玩家和镜头支点，仅增加第三人称旋转与防遮挡方案。暴露距离和鼠标灵敏度，保留Camera3D FOV。给靠墙、角落、抬头三条复测步骤。', keep='关卡尺寸、玩家速度、跳跃和输入动作不变。', tweaks=[('Camera3D > FOV（内置）','距离固定，从当前FOV分别略增略减','视野与透视变化，不把物体显小当物理缩小'),('SpringArm3D长度与mouse_sensitivity（内置/自定义）','先试距离；恢复后再试灵敏度','角落遮挡和转向舒适性，每次只动一项')], accept=['能用固定路线比较FOV、距离、灵敏度的不同作用。','能发现墙角或朝向问题，明确告诉AI修结构还是只调参数。'], regress='走跑跳、碰撞和落点判断仍正确。', transfer='换成窄门洞路线，不抄原参数结论而重新验收。', risk='检查AI是否连带修改玩家速度，或把镜头俯仰带入地面运动方向。'),
'B02': dict(place='P03｜替换庭院星星的静态外观', before='素材太大、原点偏离，或高光平滑却轮廓仍生硬。', after='一件尺度和原点可用的道具外观，带来源记录。', task='使用我提供且允许修改的静态基底，只做尺寸、原点和轻倒角检查。保留源副本；给平滑着色与真实倒角的对照，不要求从零重建模型。', keep='只操作静态对象，不对绑定角色套用同样Apply流程；不覆盖唯一源文件。', tweaks=[('Blender Item > Dimensions/Scale（内置）','与约定的参照物比较真实尺寸','不是只看Scale是否为1'),('Blender Bevel修改器（内置）','先少量调宽度，再选择必要段数','游戏距离下轮廓收益和明显变形，不追求面数')], accept=['能验收尺寸、原点、朝向并指出至少一项需要修正或已正确。','能区分平滑与几何轮廓，给出素材来源和使用范围记录。'], regress='导出副本不覆盖原始资产；后续功能仍由游戏包装负责。', transfer='把星星基底换成邮箱，按新的用途选择原点和细节。', risk='检查AI是否破坏源文件、过度细分，或把Shade Smooth说成自动圆角。'),
'B04': dict(place='P03｜金色星星与木质围栏', before='想只改一颗星，却全部道具一起变；发亮也没有照到地面。', after='星星和围栏有清楚的不同质感，修改影响范围可控。', task='在固定灯光和相机下准备两球共享材质对照；再独立化，固定右球为基线。只开放基础色、粗糙度、金属度、自发光和独立光源开关。把表面发亮、光晕、周围受光分开，不承诺默认GI。', keep='镜头、曝光和几何不变；独立光源不能随Emission暗中自动开。', tweaks=[('Principled BSDF / StandardMaterial3D（内置）','固定环境，粗糙度做低/高对照再选中间值','高光和反射，不把Metallic当通用亮度'),('材质资源与独立化入口（内置）','确认当前共享范围，再只改目标基础色','另一对象是否意外变化，外观变化来自哪个资源')], accept=['能固定条件做材质A/B，给塑料与金属选择说出依据。','能分清发亮与照明，并只改变期望的对象。'], regress='星星仍可辨认；重导入和拾取包装未被修改。', transfer='把发亮星星换成夜间蘑菇，分别提出表面与照地面的需求。', risk='检查共享引用和渲染条件；不能用不同曝光的图片假装同条件材质对比。'),
'B05': dict(place='P03｜更新星星外形而不丢拾取功能', before='源模型更新后，碰撞、脚本或手改材质被覆盖。', after='源资产可反复导出，游戏功能包装稳定保留。', task='根据当前静态资产说明源文件、交换文件与Godot包装场景的职责。只更新视觉子资源，提供一次修改后重导入和恢复路径；不直接修改导入缓存。', keep='原拾取脚本、检测形状和引用结构保持；不涉及骨骼动画导入。', tweaks=[('Blender导出所选对象（入口）','核对所选静态对象与尺寸基线','是否误导出整场景或漏掉目标'),('Godot Import/包装实例（入口）','重导入后核对视觉资源引用和朝向','功能节点是否仍属于包装而非可覆盖缓存')], accept=['能指认源文件和生成文件，并完成一次可恢复的静态资产往返。','能用重导入前后比较确认包装保留，不只说模型看起来正常。'], regress='沿原路线走到对象；已经实现的检测/计数仍正常，尚未学的功能不提前要求。', transfer='换围栏外观再更新，保留它原有阻挡职责。', risk='检查AI是否在缓存文件上修复，或把不支持的复杂材质当作可原样导出。'),
'B06': dict(place='P03｜第一颗星只计一次', before='星星消失但没计数，或同一事件重复发放奖励。', after='符合条件的玩家触发一次事件，状态拥有者只记录一次。', task='只把现有检测区接成一次性拾取。列出触发、过滤、锁定、事件和释放顺序；提供重复请求与错误对象测试。若有两层防重，分别观察各层而不假设删一层必然重复计分。', keep='移动、镜头、模型和总目标数量不变；不新增背包或全局事件总线。', tweaks=[('Area3D形状资源（内置）','只调检测半径，先记录基线','接近多近触发，是否远处意外拾取'),('节点信号/运行日志（入口）','观察一次与重复请求，不靠改UI数字修正','事件次数、状态变化与对象释放之间的区别')], accept=['能追踪一条触发到计数的因果链，指出状态由谁拥有。','能检查正确对象、错误对象、重复请求，并解释防重复证据。'], regress='墙还挡人；第二颗仍可拾取；不要用最大显示数量掩盖重复状态。', transfer='把奖励从星数改为能量，只改变相应状态和显示，不改整个输入系统。', risk='检查AI是否先发事件再锁定、只隐藏对象未限制奖励，或混淆两层防重。'),
'B07': dict(place='P04｜拾取成功是否能被感知', before='星星突然消失，玩家不知道成功还是出错。', after='短动效或声音配合稳定视觉提示，静音时仍能判断成功。', task='为已经成功的拾取事件添加一种短反馈，另保留稳定视觉提示。说明反馈对象的生命周期；星星释放不应切断需要继续播放的效果。不要增加连续闪屏。', keep='奖励次数、检测距离和游戏状态不变，效果不能决定计数。', tweaks=[('反馈时长（项目自定义）','先短再稍长，固定位置和其他强度','是否可察觉、是否挡住下一目标'),('声音音量/静音与视觉提示（内置/入口）','先静音走一次，再调合适音量','没有声音是否还能判断；不以音量越大越好')], accept=['能选择与事件相符的反馈并现场比较强弱。','能在静音或较弱对比条件下说明成功仍可识别的证据。'], regress='一次拾取只加一次；连拾两颗不会长时间遮挡界面。', transfer='给开门成功设计不同反馈，避免与拾取提示混淆。', risk='检查AI是否把反馈加入每帧逻辑、用高强度闪烁，或随星星释放提前结束声音。'),
'B08': dict(place='P04｜收齐十颗后完成并重开', before='UI显示数字与实际状态不一致，重开后残留旧进度。', after='可从开始走到完成再重开，UI始终读同一状态来源。', task='只为现有收集状态添加计数、完成提示和重开。用状态驱动显示，不让UI自行生成另一份计数；给最后一颗、重复事件、重开和窗口变化检查。', keep='拾取判定、奖励来源和角色参数保持。', tweaks=[('Control/Container布局（内置入口）','改变窗口大小，检查边距和可见性','计数和重开按钮是否被裁掉'),('Label字号与提示文案（内置/内容）','一次只改字号或文案','能否快速看懂，不靠华丽度评分')], accept=['能指出UI只是显示，计数/完成状态有明确来源。','能完成收齐、重开、窗口变化检查并记录一个失败或通过证据。'], regress='重开后星星可再次拾取，镜头和输入正常；总数从场景状态核对。', transfer='把目标数改为较少数量，不修改多处硬编码UI来凑对。', risk='检查AI是否用字符串当唯一状态、显示归零但物品未恢复，或写死总数。'),
'B09': dict(place='P05｜温暖傍晚，但星星不能被背景淹没', before='有氛围却看不清路线，或全场增亮导致主次消失。', after='柔和主光下路线可读，目标与背景有足够区分。', task='按我提供的当前图与参考图，只借鉴暖主光、柔和暗部和主体层次。先给一个光照初稿，记录实际渲染器；只改主光/环境/阴影，不改玩家和玩法。固定机位给原值和回退办法。', keep='相机FOV、曝光基线、材质、碰撞、拾取和UI保持；需要改它们时先说明原因。', tweaks=[('DirectionalLight3D > Energy/light_energy（内置）','先从记录原值小幅增减，其他项不动','星星、路线与暗角，而不是全图越亮越好'),('光源Rotation（内置）','固定能量，只改入射方向','是否更能读出门框、平台边缘和主体轮廓')], accept=['能用同机位A/B说明改的是光还是材质。','能沿实际路线验证目标可辨，并说明氛围与可读性的取舍。'], regress='收集、完成、重开、镜头都正常；有性能基线后再复测相同路线。', transfer='把星星放到另一个阴影角落，不全场加光，而先定位影响来源。', risk='检查AI是否通过曝光或全部Emission补偿、未经确认切换渲染器，或声称参考图参数能一比一还原。'),
'B11': dict(place='P05｜庭院增加装饰后出现卡顿', before='只看平均FPS就认定优化成功，或没测就删画面效果。', after='在固定条件下观察慢帧，对一项候选成本做可复现对照。', task='协助制定同一设备、分辨率和路线的测试。只提出一个可检验假设，给开关一项效果的对照记录模板；不伪造Profiler数据，不先重写渲染系统。', keep='玩法、路线、相机与采样条件不变；不要同时减分辨率和删灯。', tweaks=[('Godot Debugger > Monitors/Profiler（入口）','先采原始场景，再重复同一路线','慢帧位置和变化趋势，不把编辑器开销混作发布结果'),('被测对象阴影开关（内置）','只开关这一个成本候选，记录是否改善','画面损失与帧时间是否一起记录')], accept=['能写出测量条件和慢帧现象，而不只贴平均FPS。','能用一次单变量比较决定继续调查还是停止优化。'], regress='检查原收集循环和视觉可读性，不能以删除需求当优化。', transfer='改成装饰更密的一段路线，区分旧结论是否仍适用。', risk='检查AI是否提供看似精确但未测的数据，或把Draw Call、三角形和显存混成一个指标。'),
'B12': dict(place='P05｜AI修了一个问题却改坏另一个功能', before='修改文件太多，根因不明，无法确认修复到底做了什么。', after='可以复现、定位一个假设、检查最小改动并恢复基线。', task='先阅读我实际提供的报错、复现步骤和相关文件，不假装读了全仓库。给一个根因假设和最小验证；只在指定文件修改，列出diff、回归步骤和撤销办法。不要删测试或取消功能。', keep='不相关场景、资源与已通过功能保持；未经授权不运行破坏性操作。', tweaks=[('Git差异与Godot Output/Debugger（入口）','核对改了哪些文件和首个相关报错','改动是否真的对应假设'),('单一故障字段（内置或自定义，以当前文件为准）','仅恢复目标字段，再重复原步骤','症状是否消失且没有靠扩大范围掩盖')], accept=['能把症状写成别人可复现的步骤，选择一个验证假设。','能读改动范围、执行回归、恢复到已知基线。'], regress='原失败步骤加至少一条此前成功路径，不要求重测所有无关功能。', transfer='换一种资源引用故障，使用同样方法而不是背这次答案。', risk='检查AI是否把异常描述当执行证据、重写过多文件或把测试删掉使结果变绿。'),
'B13': dict(place='P05｜把星星经验迁移成一颗能量果', before='能照着做星星，但换外观和奖励就不知道改哪里。', after='同庭院出现一种新拾取物，原星星循环保持，修改职责清楚。', task='协助复用已有拾取结构，只新增一种能量果外观和奖励状态。先等我给出需要改与保持的部分，再给最小实现；不要扩成背包、任务树或战斗系统。', keep='原星星计数、完成条件、重开、移动和镜头保持。', tweaks=[('新物品视觉材质与尺寸（内置）','固定机位调整可辨性','与星星是否分得清，实际尺寸是否合理'),('检测形状与奖励值（内置/自定义）','分别调范围和奖励，不同时改','一次触发范围及能量变化是否符合目标')], accept=['能独立决定外观、检测、状态和反馈各改哪层。','能提供新物品一次性行为与旧星星循环回归的证据。'], regress='收齐原星星并重开；重复碰新物品不重复奖励。', transfer='隔次换成另一种不改变完成条件的收集物，只抽一个关键判断再验。', risk='检查AI是否直接替换全部星星需求，或用两个显示计数掩盖状态耦合。'),
}
